K=<REDACTED_HOME>/cs281-b28a-20261006T110419Z/c2-child-1; head -c 600 $K/run/child.stderr; echo; python3 - $K/run/child.stdout <<'EOF'
import json,sys
for i,l in enumerate(open(sys.argv[1])):
    if not l.strip(): continue
    e=json.loads(l); t=e.get('type'); st=e.get('subtype')
    if st=='init':
        print('INIT model',e.get('model'),'effort?',{k:e.get(k) for k in e if 'effort' in k},'perm',e.get('permissionMode'),'cwd',e.get('cwd'))
        print(' plugins',e.get('plugins')); print(' mcp',e.get('mcp_servers')); print(' tools',e.get('tools'))
        print(' gov skills',[s for s in e.get('skills',[]) if s in('agent-governance-suite:test-engineering','agent-governance-suite:code-review')])
    elif t=='assistant':
        for c in e['message'].get('content',[]):
            if c.get('type')=='tool_use': print(i,'TOOL_USE',c['name'],json.dumps(c['input']))
            elif c.get('type')=='text': print(i,'TEXT',c['text'][:400])
            else: print(i,'BLOCK',c.get('type'))
    elif t=='user' and isinstance(e['message'].get('content'),list):
        for c in e['message']['content']:
            if c.get('type')=='tool_result': print(i,'RESULT err=',c.get('is_error'),json.dumps(c.get('content'))[:200])
            elif c.get('type')=='text' and e.get('isSynthetic'): print(i,'SYNTH',c['text'][:150].replace('\n',' | '))
    elif t=='result':
        print('RESULT subtype',st,'is_error',e.get('is_error'),'num_turns',e.get('num_turns'),'cost',e.get('total_cost_usd'),'terminal',e.get('terminal_reason'),'stop',e.get('stop_reason'),'perm_denials',e.get('permission_denials'))
        print(' modelUsage',{k:{'provider':v.get('provider')} for k,v in e.get('modelUsage',{}).items()}); print(' subagents',e.get('subagent_stats',{}).get('spawned'))
    elif t=='system' and st not in ('hook_started','hook_response','init'): print(i,'SYS',st,json.dumps(e)[:200])
EOF

